perl -e '
open(F, "/app/sequences.fasta") or die;
my @lines = <F>;
chomp @lines;
my $i = $lines[1];
my $o = $lines[3];

# find first different position
my $n = length($i) < length($o) ? length($i) : length($o);
my $first_diff = -1;
for (my $k = 0; $k < $n; $k++) {
    if (substr($i, $k, 1) ne substr($o, $k, 1)) {
        $first_diff = $k;
        last;
    }
}
print "first difference at index: $first_diff\n";
print "input around: ", substr($i, $first_diff-20, 60), "\n";
print "output around: ", substr($o, $first_diff-20, 100), "\n";

# find end of difference
my $last_i = $first_diff;
my $last_o = $first_diff;
# walk both
my $i2 = $i;
my $o2 = $o;
my $k = 0;
while ($k < length($i2) && $k < length($o2) && substr($i2,$k,1) eq substr($o2,$k,1)) { $k++; }
print "front match: $k\n";
my $ki = length($i2)-1;
my $ko = length($o2)-1;
while ($ki >=0 && $ko >=0 && substr($i2,$ki,1) eq substr($o2,$ko,1)) { $ki--; $ko--; }
print "back of input: $ki\n";
print "back of output: $ko\n";
'

