perl -e '
open(F, "/app/sequences.fasta") or die;
my @lines = <F>;
chomp @lines;
my $i = $lines[1];
my $o = $lines[3];

# Walk both, find the insertion
my $ki = 0;
my $ko = 0;
while ($ki < length($i) && $ko < length($o) && substr($i,$ki,1) eq substr($o,$ko,1)) {
    $ki++;
    $ko++;
}
print "first diff at input pos $ki, output pos $ko\n";

my $insertion_start_o = $ko;
# Now from input, find a long match in output
my $tail = substr($i, $ki, 30);
print "input tail at $ki: $tail\n";
my $match_pos = index($o, $tail);
print "match in output at: $match_pos\n";

# After the diff, find when they realign
$ki2 = $ki;
$ko2 = $match_pos;
while (substr($i,$ki2,1) eq substr($o,$ko2,1)) {
    $ki2++;
    $ko2++;
}
print "after diff, realign at input $ki2, output $ko2\n";

# So the insertion in output is from $insertion_start_o to $match_pos
my $insertion = substr($o, $insertion_start_o, $match_pos - $insertion_start_o);
print "INSERTION (", $match_pos - $insertion_start_o, " bp): $insertion\n";

my $ins_pos_i = $ki;   # input position right before insertion
my $ins_pos_o = $insertion_start_o;  # output position right before insertion
print "Insertion point input: $ins_pos_i (between ", substr($i,$ins_pos_i-10,10), " and ", substr($i,$ins_pos_i,10), ")\n";
print "Insertion point output: $ins_pos_o (between ", substr($o,$ins_pos_o-10,10), " and ", substr($o,$ins_pos_o,10), ")\n";
'

