perl -e '
open(F, "/app/sequences.fasta") or die;
my @lines = <F>;
chomp @lines;
my $i = $lines[1];

# Forward annealing starts at pos 215 (0-indexed)
my $fp_start = 215;
# Reverse annealing ends at pos 214, so spans some range ending at 214

foreach my $fp_len (15,18,20,22,25,30,35,40,45) {
    my $seq = substr($i, $fp_start, $fp_len);
    my $tm = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 "$seq"`;
    chomp $tm;
