perl -e '
open(F, "/app/sequences.fasta") or die;
my @lines = <F>;
chomp @lines;
my $i = $lines[1];

# FP annealing
my $fp_anneal = substr($i, 215, 16);
print "FP annealing: $fp_anneal (len ", length($fp_anneal), ")\n";
my $fp_tm = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 "$fp_anneal"`;
print "FP Tm: $fp_tm";

# Reverse primer
my $rp_seq = substr($i, 215-34, 34);
my $rp_anneal = reverse($rp_seq);
$rp_anneal =~ tr/ACGTacgt/TGCAtgca/;
print "RP annealing (5->3): $rp_anneal (len ", length($rp_anneal), ")\n";
my $rp_tm = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 "$rp_seq"`;
print "RP Tm: $rp_tm";

my $diff = abs($fp_tm - $rp_tm);
print "Tm diff: $diff\n";

# Full forward primer
my $insertion = "tagattagaagaagaattaagaagaagattaacagaaag";
my $fp_full = $insertion . $fp_anneal;
print "Full FP: $fp_full (len ", length($fp_full), ")\n";
print "Full RP: $rp_anneal (len ", length($rp_anneal), ")\n";
'

perl -e '
# Verify the design by simulating the assembly: input + insertion should yield output (circularly)
open(F, "/app/sequences.fasta") or die;
my @lines = <F>;
chomp @lines;
my $i = $lines[1];
my $o = $lines[3];

# Open primers
open(P, "/app/primers.fasta") or die;
my @plines = <P>;
chomp @plines;
my ($fp, $rp);
for (my $k = 0; $k < @plines; $k++) {
    if ($plines[$k] =~ /forward/i) { $fp = $plines[$k+1]; }
    if ($plines[$k] =~ /reverse/i) { $rp = $plines[$k+1]; }
}
print "FP: $fp\n";
print "RP: $rp\n";

# Simulate PCR on circular input
# First cycle: FP extends around plasmid from insert site, RP extends the other way
# After many cycles, the major product is the linear plasmid with insertion overhang filled in
# PCR product (sense strand at end): from FP_anneal through plasmid, then RP_anneal (rc)

# Simulate Q5 SDM: KLD treatment produces a circular plasmid
# The product of PCR with FP=insert+anneal_down and RP=rc_anneal_up gives a linear dsDNA
# Ligation produces circular: the linear contains [downstream_anneal ... rest_of_plasmid ... upstream_anneal_rc] -> upon ligation yields the modified plasmid

# Let us simulate: annealing FP on input produces extension. The 3 end of FP is the annealing portion
# which is `caagggcgaggagctg` matching input pos 215+.
# Extension goes from pos 215+16 onward all around the plasmid back to insert site
# Similarly, RP (annealing portion is rc of pos 181..214) anneals on antisense strand ending at pos 214
# Extension goes from pos 214-34 backward (lower positions) until insert site.

# The PCR product on sense strand is: pos 215 onward, around, back to pos 214, then with the insertion prepended (because FP has the insertion as 5 overhang, in subsequent cycles FP can use the upper strand of the PCR product as template, creating the full insertion)

# Net result on circular plasmid: replace input[215..214] (the empty range) with the insertion sequence
my $insertion = "tagattagaagaagaattaagaagaagattaacagaaag";

my $before = substr($i, 0, 215);
my $after = substr($i, 215);
my $simulated = $before . $insertion . $after;
$simulated .= $simulated;  # concatemerize to handle circularity comparison
my $o_doubled = $o x 2;

# Find $simulated in $o_doubled
my $match_pos = index($o_doubled, $simulated);
print "Match found at position: $match_pos (expected 0)\n";

# Also verify diff in Tm/len
my $fp_anneal = substr($i, 215, 16);
my $rp_anneal_sense = substr($i, 215-34, 34);

my $fp_tm = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 "$fp_anneal"`;
my $rp_tm = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 "$rp_anneal_sense"`;
chomp($fp_tm, $rp_tm);
my $diff = abs($fp_tm - $rp_tm);
print "FP annealing len: ", length($fp_anneal), " Tm: $fp_tm\n";
print "RP annealing len: ", length($rp_anneal_sense), " Tm: $rp_tm\n";
print "Tm difference: ", sprintf("%.2f", $diff), " C\n";
print "Constraints check:\n";
print "  FP anneal length 15-45: ", (length($fp_anneal) >= 15 && length($fp_anneal) <= 45 ? "PASS" : "FAIL"), "\n";
print "  RP anneal length 15-45: ", (length($rp_anneal_sense) >= 15 && length($rp_anneal_sense) <= 45 ? "PASS" : "FAIL"), "\n";
print "  FP Tm 58-72: ", ($fp_tm >= 58 && $fp_tm <= 72 ? "PASS" : "FAIL"), "\n";
print "  RP Tm 58-72: ", ($rp_tm >= 58 && $rp_tm <= 72 ? "PASS" : "FAIL"), "\n";
print "  Tm diff <=5: ", ($diff <= 5 ? "PASS" : "FAIL"), "\n";
'
